function a(t){return String(t).padStart(2,"0")}function s(t){const e=new Date(Date.UTC(t.getFullYear(),t.getMonth(),t.getDate())),n=e.getUTCDay()||7;e.setUTCDate(e.getUTCDate()+4-n);const o=new Date(Date.UTC(e.getUTCFullYear(),0,1)),u=Math.ceil(((e.getTime()-o.getTime())/864e5+1)/7);return{year:e.getUTCFullYear(),week:u}}function g(t){const{year:e,week:n}=s(t);return`${e}-W${a(n)}`}function c(t){const e=new Date(t),n=(e.getDay()+6)%7;return e.setDate(e.getDate()-n),e}function r(t){return`${a(t.getDate())}.${a(t.getMonth()+1)}.`}function D(t){const e=c(t),n=new Date(e);return n.setDate(n.getDate()+6),`${r(e)}–${r(n)}`}export{D as a,s as i,g as w};
